// Simple duplicate check by email
const incomingEmail = ($input.first().json.email || '').toLowerCase().trim();
const existingRows = $input.all();

let isDuplicate = false;
for (const row of existingRows) {
  const existingEmail = (row.json.Email || row.json.email || '').toLowerCase().trim();
  if (existingEmail && existingEmail === incomingEmail) {
    isDuplicate = true;
    break;
  }
}

return [{
  json: {
    ...$('Clean & Structure Data').first().json,
    is_duplicate: isDuplicate
  }
}];

