// Parse AI JSON response safely
const aiRaw = $input.first().json.message?.content || $input.first().json.text || $input.first().json.output || '';
let parsed = {
  service_requested: 'Other',
  approximate_budget: 'Not specified',
  lead_priority: 'WARM',
  summary: 'Could not generate summary'
};

try {
  // Clean possible markdown code blocks
  let clean = aiRaw.replace(/```json/gi, '').replace(/```/g, '').trim();
  parsed = JSON.parse(clean);
} catch (e) {
  // fallback - try to extract fields with simple regex if pure JSON fails
  console.log('AI parse error, using fallback');
}

const original = $('Duplicate Check Logic').first().json;

return [{
  json: {
    name: original.name || '',
    email: original.email || '',
    phone: original.phone || '',
    message: original.message || '',
    service_requested: parsed.service_requested || 'Other',
    approximate_budget: parsed.approximate_budget || 'Not specified',
    lead_priority: (parsed.lead_priority || 'WARM').toUpperCase(),
    summary: parsed.summary || '',
    received_at: original.received_at,
    is_duplicate: false
  }
}];

